export const up = (db: Database) => {
  db.pragma('foreign_keys = OFF');
  db.transaction(() => {
    db.exec(`
      CREATE TABLE concepts_new (
        id INTEGER PRIMARY KEY,
        slug TEXT NOT NULL UNIQUE,
        name TEXT NOT NULL,
        tier INTEGER NOT NULL DEFAULT 2
      );
      INSERT INTO concepts_new (id, slug, name, tier)
        SELECT id, slug, name, tier FROM concepts GROUP BY slug;
      DROP TABLE concepts;
      ALTER TABLE concepts_new RENAME TO concepts;
    `);
    const broken = db.pragma('foreign_key_check') as unknown[];
    if (broken.length > 0) throw new Error('foreign key violations after rebuild');
  })();
  db.pragma('foreign_keys = ON');
};
